impl<'src> Justfile<'src> {
  fn find_suggestion(
    input: &str,
    candidates: impl Iterator<Item = Suggestion<'src>>,
  ) -> Option<Suggestion<'src>> {
    candidates
      .map(|suggestion| (edit_distance(input, suggestion.name), suggestion))
      .filter(|(distance, _suggestion)| *distance < 3)
      .min_by_key(|(distance, _suggestion)| *distance)
      .map(|(_distance, suggestion)| suggestion)
  }

  pub(crate) fn suggest_recipe(&self, input: &str) -> Option<Suggestion<'src>> {
    Self::find_suggestion(
      input,
      self
        .recipes
        .values()
        .filter(|recipe| recipe.is_public())
        .map(|recipe| Suggestion {
          name: recipe.name(),
          target: None,
        })
        .chain(
          self
            .aliases
            .values()
            .filter(|alias| alias.is_public())
            .map(|alias| Suggestion {
              name: alias.name.lexeme(),
              target: Some(alias.target.name.lexeme()),
            }),
        ),
    )
  }

  pub(crate) fn suggest_submodule(&self, input: &str) -> Option<Suggestion<'src>> {
    Self::find_suggestion(
      input,
      self
        .modules
        .keys()
        .map(|name| Suggestion { name, target: None }),
    )
  }

  pub(crate) fn suggest_variable_or_submodule(&self, input: &str) -> Option<Suggestion<'src>> {
    Self::find_suggestion(
      input,
      self
        .assignments
        .keys()
        .chain(self.modules.keys())
        .map(|name| Suggestion { name, target: None }),
    )
  }

  fn evaluate_scopes<'run>(
    &'run self,
    config: &'run Config,
    dotenv_arena: &'run Arena<BTreeMap<String, String>>,
    overrides: &'run HashMap<Number, String>,
    parent_dotenv: Option<&'run BTreeMap<String, String>>,
    root: &'run Scope<'src, 'run>,
    scope_arena: &'run Arena<Scope<'src, 'run>>,
    scopes: &mut Scopes<'src, 'run>,
    search: &'run Search,
    variable_references: Option<&HashSet<Number>>,
  ) -> RunResult<'src> {
    let dotenv = if config.load_dotenv {
      let working_directory = if self.is_submodule() {
        &self.working_directory
      } else {
        &search.working_directory
      };
      load_dotenv(config, &self.settings, working_directory)?
    } else {
      BTreeMap::new()
    };

    let dotenv = if let Some(parent_dotenv) = parent_dotenv {
      parent_dotenv
        .iter()
        .map(|(key, value)| (key.clone(), value.clone()))
        .chain(dotenv)
        .collect()
    } else {
      dotenv
    };

    let dotenv = dotenv_arena.alloc(dotenv);

    let scope = Evaluator::evaluate_assignments(
      config,
      dotenv,
      self,
      overrides,
      root,
      search,
      variable_references,
    )?;

    let scope = scope_arena.alloc(scope);
    scopes.insert(self.module_path.clone(), (self, scope, dotenv));

    for module in self.modules.values() {
      module.evaluate_scopes(
        config,
        dotenv_arena,
        overrides,
        Some(dotenv),
        scope,
        scope_arena,
        scopes,
        search,
        variable_references,
      )?;
    }

    Ok(())
  }

  pub(crate) fn run(
    &self,
    config: &Config,
    search: &Search,
    arguments: &[String],
    overrides: &HashMap<Number, String>,
  ) -> RunResult<'src> {
    let root = Scope::root();
    let dotenv_arena = Arena::new();
    let scope_arena = Arena::new();
    let mut scopes = BTreeMap::new();

    match &config.subcommand {
      Subcommand::Choose { .. } | Subcommand::Run { .. } => {
        let arguments = arguments.iter().map(String::as_str).collect::<Vec<&str>>();

        let invocations = InvocationParser::parse_invocations(self, &arguments)?;

        if config.one && invocations.len() > 1 {
          return Err(Error::ExcessInvocations {
            invocations: invocations.len(),
          });
        }

        let variable_references = if self.settings.lazy {
          let mut variable_references = HashSet::new();

          let mut stack = Vec::new();

          for invocation in &invocations {
            stack.push(invocation.recipe);
          }

          while let Some(recipe) = stack.pop() {
            variable_references.extend(&recipe.variable_references);
            for dependency in &recipe.dependencies {
              stack.push(&dependency.recipe);
            }
          }

          Some(variable_references)
        } else {
          None
        };

        self.evaluate_scopes(
          config,
          &dotenv_arena,
          overrides,
          None,
          &root,
          &scope_arena,
          &mut scopes,
          search,
          variable_references.as_ref(),
        )?;

        let ran = Ran::default();
        for invocation in invocations {
          Self::run_recipe(
            &invocation.arguments,
            config,
            false,
            &ran,
            invocation.recipe,
            &scopes,
            search,
          )?;
        }

        Ok(())
      }
      Subcommand::Command {
        binary, arguments, ..
      } => {
        let mut command = if config.shell_command {
          let mut command = self.settings.shell_command(config);
          command.arg(binary);
          command
        } else {
          Command::resolve(binary)
        };

        command
          .args(arguments)
          .current_dir(&search.working_directory);

        self.evaluate_scopes(
          config,
          &dotenv_arena,
          overrides,
          None,
          &root,
          &scope_arena,
          &mut scopes,
          search,
          Some(HashSet::new()).as_ref(),
        )?;

        let (_module, scope, dotenv) = scopes.get(&self.module_path).unwrap();
        let scope = scope.child();

        command.export(&self.settings, dotenv, &scope, &self.unexports);

        let (result, caught) = command.status_guard();

        let status = result.map_err(|io_error| Error::CommandInvoke {
          binary: binary.clone(),
          arguments: arguments.clone(),
          io_error,
        })?;

        if !status.success() {
          return Err(Error::CommandStatus {
            binary: binary.clone(),
            arguments: arguments.clone(),
            status,
          });
        }

        if let Some(signal) = caught {
          return Err(Error::Interrupted { signal });
        }

        Ok(())
      }
      Subcommand::Evaluate { format, path } => {
        let (module, variable, variable_references) = self.evaluation_target(path)?;

        self.evaluate_scopes(
          config,
          &dotenv_arena,
          overrides,
          None,
          &root,
          &scope_arena,
          &mut scopes,
          search,
          Some(&variable_references),
        )?;

        let scope = scopes.get(&module.module_path).unwrap().1;

        if let Some(variable) = variable {
          print!("{}", scope.value(variable).unwrap());
        } else {
          let width = scope.names().fold(0, |max, name| name.len().max(max));

          for binding in scope.bindings() {
            if !binding.private {
              match format {
                EvaluateFormat::Just => {
                  println!("{0:1$} := \"{2}\"", binding.name, width, binding.value);
                }
                EvaluateFormat::Shell => {
                  if binding.export || module.settings.export {
                    print!("export ");
                  }
                  print!("{}=\"", binding.name.lexeme().replace('-', "_"));
                  for c in binding.value.chars() {
                    if matches!(c, '!' | '"' | '$' | '\\' | '`') {
                      print!("\\");
                    }
                    print!("{c}");
                  }
                  println!("\"");
                }
              }
            }
          }
        }

        Ok(())
      }
      _ => unreachable!(),
    }
  }

use super::*;

/// An expression. Note that the Just language grammar has both an `expression`
/// production of additions (`a + b`) and values, and a `value` production of
/// all other value types (for example strings, function calls, and
/// parenthetical groups).
///
/// The parser parses both values and expressions into `Expression`s.
#[derive(PartialEq, Eq, Debug, Clone, Ord, PartialOrd)]
pub(crate) enum Expression<'src> {
  /// `lhs && rhs`
  And { lhs: Box<Self>, rhs: Box<Self> },
  /// `assert(condition, error)`
  Assert {
    name: Name<'src>,
    condition: Condition<'src>,
    error: Box<Self>,
  },
  /// `contents`
  Backtick {
    contents: String,
    token: Token<'src>,
  },
  /// `name(arguments)`
  Call {
    name: Name<'src>,
    arguments: Vec<Expression<'src>>,
  },
  /// `lhs + rhs`
  Concatenation { lhs: Box<Self>, rhs: Box<Self> },
  /// `if condition { then } else { otherwise }`
  Conditional {
    condition: Condition<'src>,
    then: Box<Self>,
    otherwise: Box<Self>,
  },
  // `f"format string"`
  FormatString {
    start: StringLiteral<'src>,
    expressions: Vec<(Self, StringLiteral<'src>)>,
  },
  /// `(contents)`
  Group { contents: Box<Self> },
  /// `lhs / rhs`
  Join {
    lhs: Option<Box<Self>>,
    rhs: Box<Self>,
  },
  /// `lhs || rhs`
  Or { lhs: Box<Self>, rhs: Box<Self> },
  /// `"string_literal"` or `'string_literal'`
  StringLiteral { string_literal: StringLiteral<'src> },
  /// `variable`
  Variable { name: Name<'src> },
}

impl<'src> Expression<'src> {
  pub(crate) fn references<'a>(&'a self) -> References<'a, 'src> {
    References::new(self)
  }
}

impl Display for Expression<'_> {
  fn fmt(&self, f: &mut Formatter) -> fmt::Result {
    match self {
      Self::And { lhs, rhs } => write!(f, "{lhs} && {rhs}"),
      Self::Assert {
        condition, error, ..
      } => write!(f, "assert({condition}, {error})"),
      Self::Backtick { token, .. } => write!(f, "{}", token.lexeme()),
      Self::Call { name, arguments } => {
        write!(f, "{name}(")?;
        for (i, argument) in arguments.iter().enumerate() {
          if i > 0 {
            write!(f, ", ")?;
          }
          write!(f, "{argument}")?;
        }
        write!(f, ")")
      }
      Self::Concatenation { lhs, rhs } => write!(f, "{lhs} + {rhs}"),
      Self::Conditional {
        condition,
        then,
        otherwise,
      } => {
        if let Self::Conditional { .. } = **otherwise {
          write!(f, "if {condition} {{ {then} }} else {otherwise}")
        } else {
          write!(f, "if {condition} {{ {then} }} else {{ {otherwise} }}")
        }
      }
      Self::FormatString { start, expressions } => {
        write!(f, "{start}")?;

        for (expression, string) in expressions {
          write!(f, "{expression}{string}")?;
        }

        Ok(())
      }
      Self::Group { contents } => write!(f, "({contents})"),
      Self::Join { lhs: None, rhs } => write!(f, "/ {rhs}"),
      Self::Join {
        lhs: Some(lhs),
        rhs,
      } => write!(f, "{lhs} / {rhs}"),
      Self::Or { lhs, rhs } => write!(f, "{lhs} || {rhs}"),
      Self::StringLiteral { string_literal } => write!(f, "{string_literal}"),
      Self::Variable { name } => write!(f, "{name}"),
    }
