pub(crate) type UnresolvedRecipe<'src> = Recipe<'src, UnresolvedDependency<'src>>;

impl<'src> UnresolvedRecipe<'src> {
  pub(crate) fn resolve(
    self,
    assignments: &Table<'src, Assignment<'src>>,
    functions: &Table<'src, FunctionDefinition<'src>>,
    modulepath: &Modulepath,
    resolved: Vec<Arc<Recipe<'src>>>,
    settings: &Settings,
  ) -> CompileResult<'src, Recipe<'src>> {
    assert_eq!(
      self.dependencies.len(),
      resolved.len(),
      "UnresolvedRecipe::resolve: dependency count not equal to resolved count: {} != {}",
      self.dependencies.len(),
      resolved.len()
    );

    let mut variable_references = HashSet::new();

    for (i, parameter) in self.parameters.iter().enumerate() {
      if let Some(expression) = &parameter.default {
        Self::resolve_expression(
          assignments,
          expression,
          functions,
          &self.parameters[..i],
          &mut variable_references,
        )?;
      }
    }

    for dependency in &self.dependencies {
      for argument in &dependency.arguments {
        Self::resolve_expression(
          assignments,
          argument,
          functions,
          &self.parameters,
          &mut variable_references,
        )?;
      }
    }

    for attribute in &self.attributes {
      if let Attribute::Confirm(Some(expression)) = attribute {
        Self::resolve_expression(
          assignments,
          expression,
          functions,
          &self.parameters,
          &mut variable_references,
        )?;
      }
    }

    for line in &self.body {
      if line.is_comment() && settings.ignore_comments {
        continue;
      }

      for fragment in &line.fragments {
        if let Fragment::Interpolation { expression, .. } = fragment {
          Self::resolve_expression(
            assignments,
            expression,
            functions,
            &self.parameters,
            &mut variable_references,
          )?;
        }
      }
    }

    for (unresolved, resolved) in self.dependencies.iter().zip(&resolved) {
      assert_eq!(unresolved.recipe.last().lexeme(), resolved.name.lexeme());
      if !resolved
        .argument_range()
        .contains(&unresolved.arguments.len())
      {
        return Err(unresolved.recipe.last().error(
          CompileErrorKind::DependencyArgumentCountMismatch {
            dependency: unresolved.recipe.clone(),
            found: unresolved.arguments.len(),
            min: resolved.min_arguments(),
            max: resolved.max_arguments(),
          },
        ));
      }
    }

    let dependencies = self
      .dependencies
      .into_iter()
      .zip(resolved)
      .map(|(unresolved, resolved)| Dependency {
        arguments: resolved.group_arguments(&unresolved.arguments),
        recipe: resolved,
      })
      .collect();

    let mut recipe_path = modulepath.clone();

    recipe_path.components.push(self.name.lexeme().into());

    Ok(Recipe {
      attributes: self.attributes,
      body: self.body,
      dependencies,
      doc: self.doc,
      file_depth: self.file_depth,
      import_offsets: self.import_offsets,
      module_path: Some(modulepath.clone()),
      name: self.name,
      parameters: self.parameters,
      priors: self.priors,
      private: self.private,
      quiet: self.quiet,
      recipe_path: Some(recipe_path),
      shebang: self.shebang,
      variable_references,
    })
  }

  fn resolve_expression(
    assignments: &Table<'src, Assignment<'src>>,
    expression: &Expression<'src>,
    functions: &Table<'src, FunctionDefinition<'src>>,
    parameters: &[Parameter],
    variable_references: &mut HashSet<Number>,
  ) -> CompileResult<'src> {
    for reference in expression.references() {
      match reference {
        Reference::Variable(variable) => {
          Self::resolve_variable(assignments, parameters, variable, variable_references)?;
        }
        Reference::Call { name, arguments } => {
          Analyzer::resolve_call(functions, name, arguments)?;
        }
      }
    }
    Ok(())
  }

  fn resolve_variable(
    assignments: &Table<'src, Assignment<'src>>,
    parameters: &[Parameter],
    variable: Name<'src>,
    variable_references: &mut HashSet<Number>,
  ) -> CompileResult<'src> {
    let name = variable.lexeme();

    if parameters.iter().any(|p| p.name.lexeme() == name) {
      Ok(())
    } else if let Some(assignment) = assignments.get(name) {
      variable_references.insert(assignment.number);
      Ok(())
    } else if constants().contains_key(name) {
      Ok(())
    } else {
      Err(variable.error(CompileErrorKind::UndefinedVariable { variable: name }))
    }
  }
}
use {super::*, CompileErrorKind::*};

#[derive(Default)]
pub(crate) struct Analyzer<'run, 'src> {
  aliases: Table<'src, Alias<'src, Namepath<'src>>>,
  assignments: Vec<&'run Binding<'src, Expression<'src>>>,
  functions: Vec<&'run FunctionDefinition<'src>>,
  modules: Table<'src, Justfile<'src>>,
  recipes: Vec<&'run Recipe<'src, UnresolvedDependency<'src>>>,
  sets: Table<'src, Set<'src>>,
  unexports: HashSet<String>,
  warnings: Vec<Warning>,
}

impl<'run, 'src> Analyzer<'run, 'src> {
  pub(crate) fn analyze(
    asts: &'run HashMap<PathBuf, Ast<'src>>,
    config: &Config,
    doc: Option<String>,
    groups: &[StringLiteral<'src>],
    loaded: &[PathBuf],
    name: Option<Name<'src>>,
    overrides: &mut HashMap<Number, String>,
    paths: &HashMap<PathBuf, PathBuf>,
    private: bool,
    root: &Path,
  ) -> RunResult<'src, Justfile<'src>> {
    Self::default().justfile(
      asts, config, doc, groups, loaded, name, overrides, paths, private, root,
    )
  }

  fn justfile(
    mut self,
    asts: &'run HashMap<PathBuf, Ast<'src>>,
    config: &Config,
    doc: Option<String>,
    groups: &[StringLiteral<'src>],
    loaded: &[PathBuf],
    name: Option<Name<'src>>,
    overrides: &mut HashMap<Number, String>,
    paths: &HashMap<PathBuf, PathBuf>,
    private: bool,
    root: &Path,
  ) -> RunResult<'src, Justfile<'src>> {
    let mut definitions = HashMap::new();
    let mut imports = HashSet::new();
    let mut unstable_features = BTreeSet::new();

    let mut stack = Vec::new();
    let ast = asts.get(root).unwrap();
    stack.push(ast);

    while let Some(ast) = stack.pop() {
      unstable_features.extend(&ast.unstable_features);

      for item in &ast.items {
        match item {
          Item::Alias(alias) => {
            Self::define(&mut definitions, alias.name, "alias", false)?;
            self.aliases.insert(alias.clone());
          }
          Item::Assignment(assignment) => {
            self.assignments.push(assignment);
          }
          Item::Comment(_) => (),
          Item::Function(function) => {
            self.functions.push(function);
          }
          Item::Import { absolute, .. } => {
            if let Some(absolute) = absolute {
              if imports.insert(absolute) {
                stack.push(asts.get(absolute).unwrap());
              }
            }
          }
          Item::Module {
            absolute,
            doc,
            groups,
            name,
            private,
            ..
          } => {
            if let Some(absolute) = absolute {
              Self::define(&mut definitions, *name, "module", false)?;
              self.modules.insert(Self::analyze(
                asts,
                config,
                doc.clone(),
                groups.as_slice(),
                loaded,
                Some(*name),
                overrides,
                paths,
                *private,
                absolute,
              )?);
            }
          }
          Item::Newline => {}
          Item::Recipe(recipe) => {
            if recipe.enabled() {
              Self::analyze_recipe(recipe)?;
              self.recipes.push(recipe);
            }
          }
          Item::Set(set) => {
            self.analyze_set(set)?;
            self.sets.insert(set.clone());
          }
          Item::Unexport { name } => {
            if !self.unexports.insert(name.lexeme().to_string()) {
              return Err(
                name
                  .error(DuplicateUnexport {
                    variable: name.lexeme(),
                  })
                  .into(),
              );
            }
          }
        }
      }

      self.warnings.extend(ast.warnings.iter().cloned());
    }

    let mut allow_duplicate_variables = false;

    for (_name, set) in &self.sets {
      if let Setting::AllowDuplicateVariables(value) = set.value {
        allow_duplicate_variables = value;
      }
    }

    let mut assignments: Table<'src, Assignment<'src>> = Table::default();
    for assignment in self.assignments {
      let variable = assignment.name.lexeme();

      if !allow_duplicate_variables && assignments.contains_key(variable) {
        return Err(assignment.name.error(DuplicateVariable { variable }).into());
      }

      if assignments
        .get(variable)
        .is_none_or(|original| assignment.file_depth <= original.file_depth)
      {
        assignments.insert(assignment.clone());
      }

      if self.unexports.contains(variable) {
        return Err(assignment.name.error(ExportUnexported { variable }).into());
      }
    }

    let mut functions = Table::<FunctionDefinition>::default();
    for function in self.functions {
      let name = function.name.lexeme();
      if let Some(first) = functions.get(name) {
        return Err(
          function
            .name
            .error(Redefinition {
              first_type: "function",
              second_type: "function",
              name,
              first: first.name.line,
            })
            .into(),
        );
      }
      functions.insert(function.clone());
    }

    AssignmentResolver::resolve_assignments(&assignments, &functions)?;

    for set in self.sets.values() {
      for expression in set.value.expressions() {
        for reference in expression.references() {
          match reference {
            Reference::Call { name, arguments } => {
              Analyzer::resolve_call(&functions, name, arguments)?;
            }
            Reference::Variable(variable) => {
              let name = variable.lexeme();
              if !assignments.contains_key(name) && !constants().contains_key(name) {
                return Err(variable.error(UndefinedVariable { variable: name }).into());
              }
            }
          }
        }
      }
    }

    let mut unknown_overrides = Vec::new();

    for ((path, name), value) in &config.overrides {
      if *path == ast.module_path {
        if let Some(assignment) = assignments.get(name) {
          overrides.insert(assignment.number, value.clone());
        } else {
          unknown_overrides.push(path.join(name));
        }
      } else if path.starts_with(&ast.module_path)
        && !self
          .modules
          .contains_key(&path.components[ast.module_path.components.len()])
