  fn parse_assignment(
    &mut self,
    attributes: AttributeSet<'src>,
    eager: bool,
    export: bool,
  ) -> CompileResult<'src, Assignment<'src>> {
    let name = self.parse_name()?;
    self.presume(ColonEquals)?;
    let value = self.parse_expression()?;

    let private = attributes.contains(AttributeDiscriminant::Private);

